#!/usr/bin/env python3
from __future__ import annotations

import datetime as _datetime
import functools
import io as _pyio
import locale as _locale
import math
import os
import random
import re
import struct
import subprocess
import sys
import tempfile
import time
from dataclasses import dataclass, field
from typing import Any, Callable, Iterable


VERSION_LINE = "Lua 5.5.1  Copyright (C) 1994-2026 Lua.org, PUC-Rio"
SHORT_VERSION = "Lua 5.5"
DEFAULT_PACKAGE_PATH = (
    "/usr/local/share/lua/5.5/?.lua;"
    "/usr/local/share/lua/5.5/?/init.lua;"
    "/usr/local/lib/lua/5.5/?.lua;"
    "/usr/local/lib/lua/5.5/?/init.lua;"
    "./?.lua;"
