PACKAGE_CONFIG = "/\n;\n?\n!\n-\n"
INT_MIN = -(1 << 63)
INT_MAX = (1 << 63) - 1
UINT_MOD = 1 << 64


def wrap_i64(value: int) -> int:
    value &= UINT_MOD - 1
    if value >= (1 << 63):
        value -= UINT_MOD
    return value


def is_lua_int(value: Any) -> bool:
    return isinstance(value, int) and not isinstance(value, bool)


def is_lua_float(value: Any) -> bool:
    return isinstance(value, float)


def is_lua_number(value: Any) -> bool:
    return is_lua_int(value) or is_lua_float(value)


def lua_truthy(value: Any) -> bool:
    return value is not None and value is not False


def normalize_table_key(value: Any) -> Any:
    if isinstance(value, float) and math.isfinite(value) and value.is_integer():
        ivalue = int(value)
        if INT_MIN <= ivalue <= INT_MAX:
            return ivalue
    return value


def lua_type_name(value: Any) -> str:
    if value is None:
        return "nil"
    if isinstance(value, bool):
        return "boolean"
    if is_lua_number(value):
        return "number"
    if isinstance(value, str):
        return "string"
    if isinstance(value, LuaTable):
        return "table"
    if isinstance(value, (LuaFunction, BuiltinFunction)):
        return "function"
    if isinstance(value, LuaCoroutine):
        return "thread"
    if isinstance(value, LuaFileHandle):
        return "userdata"
    return "userdata"


def lua_math_type(value: Any) -> str | None:
    if is_lua_int(value):
        return "integer"
    if is_lua_float(value):
        return "float"
    return None


def float_signbit(value: float) -> bool:
    return math.copysign(1.0, value) < 0.0


def lua_number_to_string(value: int | float) -> str:
    if is_lua_int(value):
        return str(value)
    if math.isnan(value):
        return "-nan" if float_signbit(value) else "nan"
    if math.isinf(value):
        return "-inf" if value < 0 else "inf"
    if value == 0.0 and float_signbit(value):
        return "-0.0"
    return format(value, ".17g")


def lua_value_to_string(value: Any, runtime: Runtime | None = None) -> str:
    if runtime is not None:
        metamethod = runtime.get_metamethod(value, "__tostring")
        if metamethod is not None:
            result = runtime.call_value(metamethod, [value], None)
            return lua_value_to_string(result[0] if result else None, None)
    if value is None:
        return "nil"
    if value is True:
        return "true"
    if value is False:
        return "false"
    if is_lua_number(value):
        return lua_number_to_string(value)
    if isinstance(value, str):
        return value
    if isinstance(value, LuaTable):
        return f"table: 0x{id(value):x}"
    if isinstance(value, LuaFunction):
        return f"function: 0x{id(value):x}"
    if isinstance(value, BuiltinFunction):
        return f"function: 0x{id(value):x}"
    if isinstance(value, LuaCoroutine):
        return f"thread: 0x{id(value):x}"
    if isinstance(value, LuaFileHandle):
        return f"file (0x{id(value.pyfile):x})"
    return f"{lua_type_name(value)}: 0x{id(value):x}"


def lua_repr_string(value: str) -> str:
    escaped = (
        value.replace("\\", "\\\\")
        .replace("\n", "\\n")
        .replace("\r", "\\r")
        .replace("\t", "\\t")
        .replace('"', '\\"')
    )
    return f'"{escaped}"'


