@dataclass
class Token:
    kind: str
    value: Any
    line: int
    column: int
    text: str

    def near(self) -> str:
        if self.kind == "EOF":
            return "<eof>"
        if self.kind == "NAME":
            return self.value
        if self.kind == "STRING":
            return "string"
        if self.kind == "NUMBER":
            return self.text
        return self.text


KEYWORDS = {
    "and",
    "break",
    "do",
    "else",
    "elseif",
    "end",
    "false",
    "for",
    "function",
    "goto",
