}


_HEX_NUMBER_RE = re.compile(
    r"0[xX](?:[0-9A-Fa-f]+(?:\.[0-9A-Fa-f]*)?|\.[0-9A-Fa-f]+)(?:[pP][+-]?\d+)?"
)
_DEC_NUMBER_RE = re.compile(r"(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?")


class Lexer:
    def __init__(self, source: str) -> None:
        self.source = source
        self.length = len(source)
        self.pos = 0
        self.line = 1
        self.column = 1
        if source.startswith("#!"):
            while self.pos < self.length and self.source[self.pos] != "\n":
                self._advance_char()

    def _peek(self, offset: int = 0) -> str:
        pos = self.pos + offset
        if pos >= self.length:
            return ""
        return self.source[pos]

    def _advance_char(self) -> str:
        ch = self._peek()
        if not ch:
            return ""
        self.pos += 1
        if ch == "\n":
            self.line += 1
            self.column = 1
        else:
            self.column += 1
        return ch

    def _match_long_bracket(self) -> tuple[int, str] | None:
        if self._peek() != "[":
            return None
        i = self.pos + 1
        eqs = 0
        while i < self.length and self.source[i] == "=":
            eqs += 1
            i += 1
        if i < self.length and self.source[i] == "[":
            return eqs, self.source[self.pos : i + 1]
        return None

    def _read_long_string(self, eqs: int) -> str:
        opening_len = 2 + eqs
        for _ in range(opening_len):
            self._advance_char()
        if self._peek() == "\n":
            self._advance_char()
        pieces: list[str] = []
        closing = "]" + ("=" * eqs) + "]"
        while self.pos < self.length:
            if self.source.startswith(closing, self.pos):
                for _ in range(len(closing)):
                    self._advance_char()
                return "".join(pieces)
            pieces.append(self._advance_char())
        raise LuaSyntaxError("unfinished long string", incomplete=True)

    def _skip_whitespace_and_comments(self) -> None:
        while True:
            ch = self._peek()
            if ch in (" ", "\t", "\r", "\n", "\f", "\v"):
                self._advance_char()
                continue
            if self.source.startswith("--", self.pos):
                self._advance_char()
                self._advance_char()
                long_open = self._match_long_bracket()
                if long_open is not None:
                    self._read_long_string(long_open[0])
                else:
                    while self.pos < self.length and self._peek() not in ("", "\n"):
                        self._advance_char()
                continue
            break

    def _read_name(self) -> Token:
        start_pos = self.pos
        start_line = self.line
        start_column = self.column
        while True:
            ch = self._peek()
            if not (ch.isalnum() or ch == "_"):
                break
            self._advance_char()
        text = self.source[start_pos : self.pos]
        kind = text if text in KEYWORDS else "NAME"
        return Token(kind, text, start_line, start_column, text)

    def _parse_numeric_literal(self, text: str) -> int | float:
        if text.lower().startswith("0x"):
            if "." in text or "p" in text.lower():
                return float.fromhex(text)
            value = int(text, 16)
            return wrap_i64(value)
        if "." in text or "e" in text.lower():
            return float(text)
        value = int(text, 10)
        if INT_MIN <= value <= INT_MAX:
            return value
        return float(text)

    def _read_number(self) -> Token:
        start_line = self.line
        start_column = self.column
        start_pos = self.pos
        text = ""
        hex_match = _HEX_NUMBER_RE.match(self.source, self.pos)
        if hex_match is not None:
            text = hex_match.group(0)
            for _ in range(len(text)):
                self._advance_char()
        else:
            dec_match = _DEC_NUMBER_RE.match(self.source, self.pos)
            if dec_match is None:
                raise LuaSyntaxError(
                    f"malformed number near '{self._peek()}'", incomplete=False
                )
            text = dec_match.group(0)
            for _ in range(len(text)):
                self._advance_char()
        value = self._parse_numeric_literal(text)
        return Token("NUMBER", value, start_line, start_column, text)

    def _read_escape(self) -> str:
        ch = self._advance_char()
        if ch == "a":
            return "\a"
        if ch == "b":
            return "\b"
        if ch == "f":
            return "\f"
        if ch == "n":
            return "\n"
        if ch == "r":
            return "\r"
        if ch == "t":
            return "\t"
        if ch == "v":
            return "\v"
        if ch in ('"', "'", "\\"):
            return ch
        if ch == "\n":
            return "\n"
        if ch == "z":
            while self._peek() and self._peek() in " \t\r\n\f\v":
                self._advance_char()
            return ""
        if ch == "x":
            digits = self._peek() + self._peek(1)
            if len(digits) < 2 or not re.fullmatch(r"[0-9A-Fa-f]{2}", digits):
                raise LuaSyntaxError("hexadecimal digit expected near '\\x'")
            self._advance_char()
            self._advance_char()
            return chr(int(digits, 16))
        if ch == "u":
            if self._advance_char() != "{":
                raise LuaSyntaxError("missing '{' near '\\u'")
            digits: list[str] = []
            while self._peek() and self._peek() != "}":
                digits.append(self._advance_char())
            if self._advance_char() != "}":
                raise LuaSyntaxError("missing '}' near '\\u'")
            return chr(int("".join(digits), 16))
        if ch.isdigit():
            digits = ch
            for _ in range(2):
                if self._peek().isdigit():
                    digits += self._advance_char()
            return chr(int(digits, 10))
        return ch

    def _read_short_string(self) -> Token:
        quote = self._advance_char()
        start_line = self.line
        start_column = self.column - 1
        pieces: list[str] = []
        while True:
            ch = self._peek()
            if ch == "":
                raise LuaSyntaxError("unfinished string near <eof>", incomplete=True)
            if ch == quote:
                self._advance_char()
                break
            if ch == "\\":
                self._advance_char()
                pieces.append(self._read_escape())
                continue
            if ch in ("\n", "\r"):
                raise LuaSyntaxError("unfinished string near <eof>", incomplete=True)
            pieces.append(self._advance_char())
        text = self.source[self.pos - (sum(len(p) for p in pieces) + 2) : self.pos]
        return Token("STRING", "".join(pieces), start_line, start_column, text)

    def next_token(self) -> Token:
        self._skip_whitespace_and_comments()
        start_line = self.line
        start_column = self.column
        ch = self._peek()
        if ch == "":
            return Token("EOF", None, start_line, start_column, "")
        if ch.isalpha() or ch == "_":
            return self._read_name()
        if ch.isdigit() or (ch == "." and self._peek(1).isdigit()):
            return self._read_number()
        if ch in ("'", '"'):
            return self._read_short_string()
        long_open = self._match_long_bracket()
        if long_open is not None:
            value = self._read_long_string(long_open[0])
            return Token("STRING", value, start_line, start_column, "")
        for op in ("...", "//", "==", "~=", "<=", ">=", "::", "<<", ">>", ".."):
            if self.source.startswith(op, self.pos):
                for _ in range(len(op)):
                    self._advance_char()
                return Token(op, op, start_line, start_column, op)
        single = self._advance_char()
        return Token(single, single, start_line, start_column, single)

    def tokenize(self) -> list[Token]:
        tokens: list[Token] = []
        while True:
            token = self.next_token()
            tokens.append(token)
            if token.kind == "EOF":
                return tokens


