class Parser:
    def __init__(self, tokens: list[Token]) -> None:
        self.tokens = tokens
        self.pos = 0
        self.vararg_stack = [True]

    def current(self) -> Token:
        return self.tokens[self.pos]

    def peek(self, offset: int = 1) -> Token:
        idx = self.pos + offset
        if idx >= len(self.tokens):
            return self.tokens[-1]
        return self.tokens[idx]

    def advance(self) -> Token:
        token = self.current()
        if self.pos < len(self.tokens) - 1:
            self.pos += 1
        return token

    def match(self, kind: str) -> Token | None:
        if self.current().kind == kind:
            return self.advance()
        return None

    def expect(self, kind: str, desc: str | None = None) -> Token:
        token = self.current()
        if token.kind == kind:
            return self.advance()
        if token.kind == "EOF":
            message = f"{desc or kind} expected near <eof>"
            raise LuaSyntaxError(message, incomplete=True)
        message = f"{desc or kind} expected near '{token.near()}'"
        raise LuaSyntaxError(message)

    def parse(self) -> Block:
        return self.parse_block({"EOF"})

    def parse_block(self, end_kinds: set[str]) -> Block:
        statements: list[Any] = []
        line = self.current().line
        while self.current().kind not in end_kinds:
            if self.current().kind == "return":
                statements.append(self.parse_return())
                self.match(";")
                break
            statements.append(self.parse_statement())
        return Block(line, statements)

    def parse_statement(self) -> Any:
        token = self.current()
        kind = token.kind
        if kind == ";":
            self.advance()
            return EmptyStat(token.line)
        if kind == "break":
            self.advance()
            return BreakStat(token.line)
        if kind == "goto":
            self.advance()
            name = self.expect("NAME", "<name>").value
            return GotoStat(token.line, name)
        if kind == "::":
            self.advance()
            name = self.expect("NAME", "<label>").value
            self.expect("::")
            return LabelStat(token.line, name)
        if kind == "do":
            self.advance()
            block = self.parse_block({"end"})
            self.expect("end")
            return DoStat(token.line, block)
        if kind == "while":
            self.advance()
            cond = self.parse_expr()
            self.expect("do")
            block = self.parse_block({"end"})
            self.expect("end")
            return WhileStat(token.line, cond, block)
        if kind == "repeat":
            self.advance()
            block = self.parse_block({"until"})
            self.expect("until")
            cond = self.parse_expr()
            return RepeatStat(token.line, block, cond)
        if kind == "if":
            return self.parse_if()
        if kind == "for":
            return self.parse_for()
        if kind == "function":
            return self.parse_function_statement()
        if kind == "local":
            return self.parse_local()
        return self.parse_assignment_or_call()

    def parse_return(self) -> ReturnStat:
        token = self.expect("return")
        if self.current().kind in {"EOF", "end", "elseif", "else", "until", ";"}:
            return ReturnStat(token.line, [])
        values = self.parse_expr_list()
        return ReturnStat(token.line, values)

    def parse_if(self) -> IfStat:
        token = self.expect("if")
        branches: list[tuple[Expr, Block]] = []
        cond = self.parse_expr()
        self.expect("then")
        block = self.parse_block({"elseif", "else", "end"})
        branches.append((cond, block))
        while self.match("elseif") is not None:
            cond = self.parse_expr()
            self.expect("then")
            block = self.parse_block({"elseif", "else", "end"})
            branches.append((cond, block))
        else_block = None
        if self.match("else") is not None:
            else_block = self.parse_block({"end"})
        self.expect("end")
        return IfStat(token.line, branches, else_block)

    def parse_for(self) -> Any:
        token = self.expect("for")
        name = self.expect("NAME", "<name>").value
        if self.match("=") is not None:
            start = self.parse_expr()
            self.expect(",")
            stop = self.parse_expr()
            step = None
            if self.match(",") is not None:
                step = self.parse_expr()
            self.expect("do")
            block = self.parse_block({"end"})
            self.expect("end")
            return NumericForStat(token.line, name, start, stop, step, block)
        names = [name]
        while self.match(",") is not None:
            names.append(self.expect("NAME", "<name>").value)
        self.expect("in")
        exps = self.parse_expr_list()
        self.expect("do")
        block = self.parse_block({"end"})
        self.expect("end")
        return GenericForStat(token.line, names, exps, block)

    def parse_function_statement(self) -> AssignStat:
        token = self.expect("function")
        path = [self.expect("NAME", "<name>").value]
        while self.match(".") is not None:
            path.append(self.expect("NAME", "<name>").value)
        method_name = None
        if self.match(":") is not None:
            method_name = self.expect("NAME", "<name>").value
        func = self.parse_function_body()
        target: Expr = VarExpr(token.line, path[0])
        for part in path[1:]:
            target = IndexExpr(token.line, target, LiteralExpr(token.line, part))
        if method_name is not None:
            target = IndexExpr(token.line, target, LiteralExpr(token.line, method_name))
            func.params = ["self", *func.params]
        func.name_hint = method_name or path[-1]
        return AssignStat(token.line, [target], [func])

    def parse_attribute(self) -> str | None:
        if self.match("<") is None:
            return None
        name = self.expect("NAME", "<name>").value
        self.expect(">")
        return name

    def parse_local(self) -> Any:
        token = self.expect("local")
        if self.match("function") is not None:
            name = self.expect("NAME", "<name>").value
            func = self.parse_function_body()
            func.name_hint = name
            return LocalFunctionStat(token.line, name, func)
        names = [self.expect("NAME", "<name>").value]
        attrs = [self.parse_attribute()]
        while self.match(",") is not None:
            names.append(self.expect("NAME", "<name>").value)
            attrs.append(self.parse_attribute())
        values: list[Expr] = []
        if self.match("=") is not None:
            values = self.parse_expr_list()
        return LocalAssignStat(token.line, names, attrs, values)

    def parse_assignment_or_call(self) -> Any:
        expr = self.parse_prefix_expr()
        if isinstance(expr, CallExpr):
            return CallStat(expr.line, expr)
        targets = [expr]
        while self.match(",") is not None:
            next_expr = self.parse_prefix_expr()
            targets.append(next_expr)
        if self.match("=") is None:
            token = self.current()
            raise LuaSyntaxError(f"syntax error near '{token.near()}'")
        values = self.parse_expr_list()
        return AssignStat(expr.line, targets, values)

    def parse_expr_list(self) -> list[Expr]:
        values = [self.parse_expr()]
        while self.match(",") is not None:
            values.append(self.parse_expr())
        return values

    def parse_expr(self, min_prec: int = 1) -> Expr:
        token = self.current()
        if token.kind in UNARY_OPS:
            self.advance()
            expr = self.parse_expr(11)
            left: Expr = UnaryExpr(token.line, token.kind, expr)
        else:
            left = self.parse_simple_expr()
        while True:
            token = self.current()
            if token.kind not in PRECEDENCE:
                break
            prec, right_assoc = PRECEDENCE[token.kind]
            if prec < min_prec:
                break
            self.advance()
            next_min = prec if right_assoc else prec + 1
            right = self.parse_expr(next_min)
            left = BinaryExpr(token.line, token.kind, left, right)
        return left

    def parse_simple_expr(self) -> Expr:
        token = self.current()
        if token.kind == "nil":
            self.advance()
            return LiteralExpr(token.line, None)
        if token.kind == "true":
            self.advance()
            return LiteralExpr(token.line, True)
        if token.kind == "false":
            self.advance()
            return LiteralExpr(token.line, False)
        if token.kind == "NUMBER":
            self.advance()
            return LiteralExpr(token.line, token.value)
        if token.kind == "STRING":
            self.advance()
            return LiteralExpr(token.line, token.value)
        if token.kind == "...":
            if not self.vararg_stack[-1]:
                raise LuaSyntaxError("cannot use '...' outside a vararg function")
            self.advance()
            return VarArgExpr(token.line)
        if token.kind == "function":
            self.advance()
            return self.parse_function_body(token.line)
        if token.kind == "{":
            return self.parse_table()
        return self.parse_prefix_expr()

    def parse_function_body(self, line: int | None = None) -> FunctionExpr:
        if line is None:
            line = self.current().line
        self.expect("(")
        params: list[str] = []
        vararg = False
        if self.current().kind != ")":
            while True:
                if self.current().kind == "...":
                    self.advance()
                    vararg = True
                    break
                params.append(self.expect("NAME", "<name>").value)
                if self.match(",") is None:
                    break
            if self.match(",") is not None:
                self.expect("...")
                vararg = True
        self.expect(")")
        self.vararg_stack.append(vararg)
        body = self.parse_block({"end"})
        self.vararg_stack.pop()
        self.expect("end")
        return FunctionExpr(line, params, vararg, body)

    def parse_table(self) -> TableExpr:
        token = self.expect("{")
        fields: list[TableField] = []
        if self.current().kind != "}":
            while True:
                if self.match("[") is not None:
                    key = self.parse_expr()
                    self.expect("]")
                    self.expect("=")
                    value = self.parse_expr()
                    fields.append(TableField("expr", key, value))
                elif self.current().kind == "NAME" and self.peek().kind == "=":
                    name = self.advance().value
                    self.expect("=")
                    value = self.parse_expr()
                    fields.append(TableField("name", name, value))
                else:
                    value = self.parse_expr()
                    fields.append(TableField("seq", None, value))
                if self.current().kind not in {",", ";"}:
                    break
                self.advance()
                if self.current().kind == "}":
                    break
        self.expect("}")
        return TableExpr(token.line, fields)

    def parse_prefix_expr(self) -> Expr:
        token = self.current()
        if token.kind == "NAME":
            expr: Expr = VarExpr(token.line, self.advance().value)
        elif token.kind == "(":
            self.advance()
            inner = self.parse_expr()
            self.expect(")")
            expr = ParenExpr(token.line, inner)
        else:
            raise LuaSyntaxError(f"unexpected symbol near '{token.near()}'")
        while True:
            token = self.current()
            if token.kind == "[":
                self.advance()
                key = self.parse_expr()
                self.expect("]")
                expr = IndexExpr(token.line, expr, key)
                continue
            if token.kind == ".":
                self.advance()
                name = self.expect("NAME", "<name>").value
                expr = IndexExpr(token.line, expr, LiteralExpr(token.line, name))
                continue
            if token.kind == ":":
                self.advance()
                name = self.expect("NAME", "<name>").value
                args = self.parse_args()
                expr = CallExpr(token.line, expr, args, name)
                continue
            if token.kind in {"(", "{", "STRING"}:
                args = self.parse_args()
                expr = CallExpr(token.line, expr, args)
                continue
            break
        return expr

    def parse_args(self) -> list[Expr]:
        if self.match("(") is not None:
            args: list[Expr] = []
            if self.current().kind != ")":
                args = self.parse_expr_list()
            self.expect(")")
            return args
        if self.current().kind == "{":
            return [self.parse_table()]
        if self.current().kind == "STRING":
            token = self.advance()
            return [LiteralExpr(token.line, token.value)]
        token = self.current()
        raise LuaSyntaxError(f"unexpected symbol near '{token.near()}'")


@dataclass
class Cell:
    value: Any = None
    const: bool = False
    close: bool = False


class Frame:
    def __init__(self, parent: Frame | None = None, varargs: list[Any] | None = None) -> None:
        self.parent = parent
        self.locals: dict[str, Cell] = {}
        self.varargs = varargs or []
        self.closables: list[tuple[str, Cell]] = []

    def define(self, name: str, value: Any, const: bool = False, close: bool = False) -> Cell:
        cell = Cell(value, const=const, close=close)
        self.locals[name] = cell
        if close:
            self.closables.append((name, cell))
        return cell

    def find(self, name: str) -> Cell | None:
        frame: Frame | None = self
        while frame is not None:
            if name in frame.locals:
                return frame.locals[name]
            frame = frame.parent
        return None


class LuaTable:
    def __init__(self) -> None:
        self.map: dict[Any, Any] = {}
        self.metatable: LuaTable | None = None

    def rawget(self, key: Any) -> Any:
        return self.map.get(normalize_table_key(key), None)

    def rawset(self, key: Any, value: Any) -> None:
        if key is None:
            raise ValueError("table index is nil")
        key = normalize_table_key(key)
        if value is None:
            self.map.pop(key, None)
        else:
            self.map[key] = value

    def rawlen(self) -> int:
        n = 0
        while True:
            n += 1
            if normalize_table_key(n) not in self.map:
                return n - 1

    def next_pair(self, key: Any) -> tuple[Any, Any]:
        keys = list(self.map.keys())
        if key is None:
            if not keys:
                return None, None
            first = keys[0]
            return first, self.map[first]
        nkey = normalize_table_key(key)
        if nkey not in self.map:
            raise KeyError("invalid key to 'next'")
        idx = keys.index(nkey) + 1
        if idx >= len(keys):
            return None, None
        next_key = keys[idx]
        return next_key, self.map[next_key]


@dataclass
class StackEntry:
    source: str
    line: int
    kind: str
    name: str | None = None
    is_c: bool = False

    def format(self) -> str:
        if self.is_c:
            if self.kind == "?":
                return "\t[C]: in ?"
            return f"\t[C]: in {self.kind} '{self.name}'"
        location = f"{self.source}:{self.line}"
        if self.kind == "main chunk":
            return f"\t{location}: in main chunk"
        return f"\t{location}: in {self.kind} '{self.name}'"


class LuaFunction:
    def __init__(
        self,
        params: list[str],
        vararg: bool,
        body: Block,
        closure: Frame,
        source_name: str,
        line: int,
        name_hint: str | None = None,
    ) -> None:
        self.params = params
        self.vararg = vararg
        self.body = body
        self.closure = closure
        self.source_name = source_name
        self.line = line
        self.name_hint = name_hint


class BuiltinFunction:
    def __init__(self, name: str, func: Callable[[Runtime, list[Any]], list[Any]]) -> None:
        self.name = name
        self.func = func

    def __call__(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        return self.func(runtime, args)


class LuaFileHandle:
    def __init__(self, pyfile: Any, closable: bool = True) -> None:
        self.pyfile = pyfile
        self.closable = closable
        self.closed = False
        self.metatable: LuaTable | None = None

    def close(self) -> tuple[bool, Any]:
        if self.closed:
            return False, "file is already closed"
        try:
            if self.closable:
                self.pyfile.close()
            self.closed = True
            return True, None
        except Exception as exc:  # pragma: no cover
            return False, str(exc)


class LuaCoroutine:
    def __init__(self, func: Any) -> None:
        self.func = func
        self.status = "suspended"
        self.started = False


