    def arg(self, args: list[Any], index: int, default: Any = None) -> Any:
        return args[index - 1] if len(args) >= index else default

    def check_string(self, args: list[Any], index: int) -> str:
        value = self.arg(args, index)
        if isinstance(value, str):
            return value
        self.type_error(index, "string", value)
        raise AssertionError

    def check_number(self, args: list[Any], index: int) -> int | float:
        value = self.arg(args, index)
        if is_lua_number(value):
            return value
        if isinstance(value, str):
            parsed = self.coerce_to_number(value)
            if parsed is not None:
                return parsed
        self.type_error(index, "number", value)
        raise AssertionError

    def check_int(self, args: list[Any], index: int) -> int:
        value = self.arg(args, index)
        ivalue = self.coerce_to_integer(value)
        if ivalue is None:
            self.raise_runtime(self.current_location_message("number has no integer representation"))
        return ivalue

    def check_table(self, args: list[Any], index: int) -> LuaTable:
        value = self.arg(args, index)
        if isinstance(value, LuaTable):
            return value
        self.type_error(index, "table", value)
        raise AssertionError

    def check_function(self, args: list[Any], index: int) -> Any:
        value = self.arg(args, index)
        if isinstance(value, (LuaFunction, BuiltinFunction)):
            return value
        self.raise_runtime(
            self.current_location_message(
                f"bad argument #{index} to '{self.call_stack[-1].name if self.call_stack else '?'}' (function expected, got {lua_type_name(value)})"
            )
        )
        raise AssertionError

    def type_error(self, index: int, expected: str, got: Any) -> None:
        name = self.call_stack[-1].name if self.call_stack else "?"
        self.raise_runtime(
            self.current_location_message(
                f"bad argument #{index} to '{name}' ({expected} expected, got {lua_type_name(got)})"
            ),
            traceback=True,
        )

    def current_location(self) -> tuple[str, int]:
        for entry in reversed(self.call_stack):
            if not entry.is_c:
                return entry.source, entry.line
        return ("(command line)", 1)

    def current_location_message(self, text: str) -> str:
        source, line = self.current_location()
        return f"{source}:{line}: {text}"

    def raise_runtime(self, value: Any, traceback: bool = True) -> None:
        raise LuaRuntimeError(value, traceback=traceback)

    def push_frame(self, entry: StackEntry) -> None:
        self.call_stack.append(entry)

    def pop_frame(self) -> None:
        if self.call_stack:
            self.call_stack.pop()

    def set_current_line(self, line: int) -> None:
        for entry in reversed(self.call_stack):
            if not entry.is_c:
                entry.line = line
                return

    def format_traceback(self) -> str:
        lines = ["stack traceback:"]
        for entry in reversed(self.call_stack):
            lines.append(entry.format())
        lines.append("\t[C]: in ?")
        return "\n".join(lines)

    def close_frame(self, frame: Frame) -> None:
        for _, cell in reversed(frame.closables):
            value = cell.value
            if value is None:
                continue
            if isinstance(value, LuaFileHandle):
                value.close()
                continue
            closer = self.get_metamethod(value, "__close")
            if closer is not None:
                try:
                    self.call_value(closer, [value, None], None)
                except LuaRuntimeError:
                    pass

    def get_env_table(self, frame: Frame) -> LuaTable:
        env_cell = frame.find("_ENV")
        if env_cell is None or not isinstance(env_cell.value, LuaTable):
            return self.global_env
        return env_cell.value

    def lookup_name(self, frame: Frame, name: str) -> Any:
        cell = frame.find(name)
        if cell is not None:
            return cell.value
        env = self.get_env_table(frame)
        return self.get_index(env, name)

    def assign_name(self, frame: Frame, name: str, value: Any) -> None:
        cell = frame.find(name)
        if cell is not None:
            if cell.const:
                self.raise_runtime(self.current_location_message(f"attempt to assign to const variable '{name}'"), traceback=False)
            if cell.close and value is not None and not self.is_closable(value):
                self.raise_runtime(self.current_location_message(f"variable '{name}' got a non-closable value"))
            cell.value = value
            return
        env = self.get_env_table(frame)
        self.set_index(env, name, value)

    def is_closable(self, value: Any) -> bool:
        return isinstance(value, LuaFileHandle) or self.get_metamethod(value, "__close") is not None

    def get_metamethod(self, value: Any, name: str) -> Any:
        metatable: LuaTable | None = None
        if isinstance(value, LuaTable):
            metatable = value.metatable
        elif isinstance(value, LuaFileHandle):
            metatable = value.metatable
        elif isinstance(value, str):
            string_mt = LuaTable()
            string_mt.rawset("__index", self.string_lib)
            metatable = string_mt
        if metatable is None:
            return None
        return metatable.rawget(name)

    def get_index(self, obj: Any, key: Any) -> Any:
        if isinstance(obj, LuaTable):
            raw = obj.rawget(key)
            if raw is not None:
                return raw
            mm = self.get_metamethod(obj, "__index")
            if mm is None:
                return None
            if isinstance(mm, LuaTable):
                return self.get_index(mm, key)
            return self.call_value(mm, [obj, key], None)[0] if self.call_value(mm, [obj, key], None) else None
        if isinstance(obj, LuaFileHandle):
            if obj.metatable is not None:
                method = obj.metatable.rawget(key)
                if method is not None:
                    return method
        if isinstance(obj, str):
            if self.string_lib is not None:
                method = self.string_lib.rawget(key)
                if method is not None:
                    return method
        self.raise_runtime(self.current_location_message(f"attempt to index a {lua_type_name(obj)} value"))
        raise AssertionError

    def set_index(self, obj: Any, key: Any, value: Any) -> None:
        if isinstance(obj, LuaTable):
            existing = obj.rawget(key)
            if existing is not None or obj.metatable is None or obj.metatable.rawget("__newindex") is None:
                obj.rawset(key, value)
                return
            mm = obj.metatable.rawget("__newindex")
            if isinstance(mm, LuaTable):
                self.set_index(mm, key, value)
                return
            self.call_value(mm, [obj, key, value], None)
            return
        self.raise_runtime(self.current_location_message(f"attempt to index a {lua_type_name(obj)} value"))

    def raw_length(self, value: Any) -> int:
        if isinstance(value, str):
            return len(value)
        if isinstance(value, LuaTable):
            return value.rawlen()
        self.raise_runtime(self.current_location_message(f"attempt to get length of a {lua_type_name(value)} value"))
        raise AssertionError

    def lua_equal(self, a: Any, b: Any) -> bool:
        if is_lua_number(a) and is_lua_number(b):
            return float(a) == float(b)
        return a is b if isinstance(a, (LuaTable, LuaFunction, BuiltinFunction, LuaCoroutine, LuaFileHandle)) else a == b

    def compare_numbers(self, a: Any, b: Any, op: str) -> bool:
        av = float(a) if is_lua_float(a) or is_lua_float(b) else a
        bv = float(b) if is_lua_float(a) or is_lua_float(b) else b
        if op == "<":
            return av < bv
        if op == "<=":
            return av <= bv
        if op == ">":
            return av > bv
        return av >= bv

    def coerce_to_number(self, value: Any, base: int | None = None) -> int | float | None:
        if is_lua_number(value):
            return value
        if not isinstance(value, str):
            return None
        text = value.strip()
        if text == "":
            return None
        try:
            if base is not None:
                if base < 2 or base > 36:
                    return None
                return int(text, base)
            if text.lower().startswith("0x"):
                if re.fullmatch(r"0[xX][0-9A-Fa-f]+", text):
                    return wrap_i64(int(text, 16))
                return float.fromhex(text)
            if re.fullmatch(r"[+-]?\d+", text):
                ivalue = int(text, 10)
                if INT_MIN <= ivalue <= INT_MAX:
                    return ivalue
                return float(text)
            return float(text)
        except Exception:
            return None

    def coerce_to_integer(self, value: Any) -> int | None:
        if is_lua_int(value):
            return value
        if is_lua_float(value) and math.isfinite(value) and value.is_integer():
            ivalue = int(value)
            if INT_MIN <= ivalue <= INT_MAX:
                return ivalue
        if isinstance(value, str):
            num = self.coerce_to_number(value)
            return self.coerce_to_integer(num) if num is not None else None
        return None

    def arithmetic_binary(self, op: str, left: Any, right: Any) -> Any:
        if op in {"&", "|", "~", "<<", ">>"}:
            li = self.coerce_to_integer(left)
            ri = self.coerce_to_integer(right)
            if li is None or ri is None:
                self.raise_runtime(self.current_location_message("number has no integer representation"))
            if op == "&":
                return wrap_i64(li & ri)
            if op == "|":
                return wrap_i64(li | ri)
            if op == "~":
                return wrap_i64(li ^ ri)
            if op == "<<":
                if ri >= 64:
                    return 0
                if ri <= -64:
                    return -1 if li < 0 else 0
                if ri < 0:
                    return wrap_i64(li >> -ri)
                return wrap_i64(li << ri)
            if ri >= 64:
                return -1 if li < 0 else 0
            if ri <= -64:
                return 0
            if ri < 0:
                return wrap_i64(li << -ri)
            return wrap_i64(li >> ri)
        if not is_lua_number(left) and not isinstance(left, str):
            self.raise_runtime(self.current_location_message(f"attempt to perform arithmetic on a {lua_type_name(left)} value"))
        if not is_lua_number(right) and not isinstance(right, str):
            self.raise_runtime(self.current_location_message(f"attempt to perform arithmetic on a {lua_type_name(right)} value"))
        ln = self.coerce_to_number(left)
        rn = self.coerce_to_number(right)
        if ln is None or rn is None:
            self.raise_runtime(self.current_location_message("attempt to perform arithmetic on a string value"))
        if op == "/":
            return float(ln) / float(rn)
        if op == "^":
            return float(ln) ** float(rn)
        if op == "//":
            if is_lua_int(ln) and is_lua_int(rn):
                return wrap_i64(math.floor(ln / rn))
            return math.floor(float(ln) / float(rn)) + 0.0
        if op == "%":
            if is_lua_int(ln) and is_lua_int(rn):
                return wrap_i64(ln - math.floor(ln / rn) * rn)
            return float(ln) - math.floor(float(ln) / float(rn)) * float(rn)
        if is_lua_int(ln) and is_lua_int(rn):
            if op == "+":
                return wrap_i64(ln + rn)
            if op == "-":
                return wrap_i64(ln - rn)
            if op == "*":
                return wrap_i64(ln * rn)
        lf = float(ln)
        rf = float(rn)
        if op == "+":
            return lf + rf
        if op == "-":
            return lf - rf
        if op == "*":
            return lf * rf
        raise AssertionError(op)

    def arithmetic_unary(self, op: str, value: Any) -> Any:
        if op == "not":
            return not lua_truthy(value)
        if op == "#":
            mm = self.get_metamethod(value, "__len")
            if mm is not None:
                result = self.call_value(mm, [value], None)
                return result[0] if result else None
            return self.raw_length(value)
        if op == "~":
            ivalue = self.coerce_to_integer(value)
            if ivalue is None:
                self.raise_runtime(self.current_location_message("number has no integer representation"))
            return wrap_i64(~ivalue)
        num = self.coerce_to_number(value)
        if num is None:
            self.raise_runtime(self.current_location_message(f"attempt to perform arithmetic on a {lua_type_name(value)} value"))
        if is_lua_int(num):
            return wrap_i64(-num)
        return -float(num)

    def compare_values(self, op: str, left: Any, right: Any) -> bool:
        if op in {"==", "~="}:
            result = self.lua_equal(left, right)
            return result if op == "==" else not result
        if is_lua_number(left) and is_lua_number(right):
            return self.compare_numbers(left, right, op)
        if isinstance(left, str) and isinstance(right, str):
            if op == "<":
                return left < right
            if op == "<=":
                return left <= right
            if op == ">":
                return left > right
            return left >= right
        self.raise_runtime(self.current_location_message(f"attempt to compare {lua_type_name(left)} with {lua_type_name(right)}"))
        raise AssertionError

    def concat_values(self, left: Any, right: Any) -> str:
        if not isinstance(left, str):
            if is_lua_number(left):
                left = lua_number_to_string(left)
            else:
                self.raise_runtime(self.current_location_message(f"attempt to concatenate a {lua_type_name(left)} value"))
        if not isinstance(right, str):
            if is_lua_number(right):
                right = lua_number_to_string(right)
            else:
                self.raise_runtime(self.current_location_message(f"attempt to concatenate a {lua_type_name(right)} value"))
        return left + right

    def eval_expr(self, expr: Expr, frame: Frame, multret: bool = False) -> list[Any]:
        if isinstance(expr, LiteralExpr):
            return [expr.value]
        if isinstance(expr, VarExpr):
            return [self.lookup_name(frame, expr.name)]
        if isinstance(expr, VarArgExpr):
            return frame.varargs[:] if multret else [frame.varargs[0] if frame.varargs else None]
        if isinstance(expr, ParenExpr):
            values = self.eval_expr(expr.expr, frame, False)
            return [values[0] if values else None]
        if isinstance(expr, UnaryExpr):
            value = self.eval_expr(expr.expr, frame, False)[0]
            return [self.arithmetic_unary(expr.op, value)]
        if isinstance(expr, BinaryExpr):
            if expr.op == "and":
                left = self.eval_expr(expr.left, frame, False)[0]
                if not lua_truthy(left):
                    return [left]
                return self.eval_expr(expr.right, frame, multret if multret else False)
            if expr.op == "or":
                left = self.eval_expr(expr.left, frame, False)[0]
                if lua_truthy(left):
                    return [left]
                return self.eval_expr(expr.right, frame, multret if multret else False)
            if expr.op == "..":
                left = self.eval_expr(expr.left, frame, False)[0]
                right = self.eval_expr(expr.right, frame, False)[0]
                return [self.concat_values(left, right)]
            left = self.eval_expr(expr.left, frame, False)[0]
            right = self.eval_expr(expr.right, frame, False)[0]
            if expr.op in PRECEDENCE and expr.op not in {"and", "or", "..", "<", ">", "<=", ">=", "==", "~="}:
                return [self.arithmetic_binary(expr.op, left, right)]
            return [self.compare_values(expr.op, left, right)]
        if isinstance(expr, TableExpr):
            table = LuaTable()
            seq_index = 1
            for index, field in enumerate(expr.fields):
                is_last = index == len(expr.fields) - 1
                if field.kind == "seq":
                    values = self.eval_expr(field.value, frame, is_last)
                    if not values:
                        values = [None]
                    for value in values:
                        table.rawset(seq_index, value)
                        seq_index += 1
                elif field.kind == "name":
                    value = self.eval_expr(field.value, frame, False)[0]
                    table.rawset(field.key, value)
                else:
                    key = self.eval_expr(field.key, frame, False)[0]
                    value = self.eval_expr(field.value, frame, False)[0]
                    table.rawset(key, value)
            return [table]
        if isinstance(expr, FunctionExpr):
            return [LuaFunction(expr.params[:], expr.vararg, expr.body, frame, self.current_location()[0], expr.line, expr.name_hint)]
        if isinstance(expr, IndexExpr):
            obj = self.eval_expr(expr.obj, frame, False)[0]
            key = self.eval_expr(expr.key, frame, False)[0]
            return [self.get_index(obj, key)]
        if isinstance(expr, CallExpr):
            return self.eval_call(expr, frame, multret)
        raise AssertionError(type(expr).__name__)

    def eval_call(self, expr: CallExpr, frame: Frame, multret: bool) -> list[Any]:
        callee = self.eval_expr(expr.func, frame, False)[0]
        args: list[Any] = []
        if expr.method_name is not None:
            obj = self.eval_expr(expr.func, frame, False)[0]
            callee = self.get_index(obj, expr.method_name)
            args.append(obj)
        for index, arg in enumerate(expr.args):
            is_last = index == len(expr.args) - 1
            values = self.eval_expr(arg, frame, is_last)
            if is_last:
                args.extend(values)
            else:
                args.append(values[0] if values else None)
        results = self.call_value(callee, args, self.describe_callee(expr, frame))
        if multret:
            return results
        return [results[0] if results else None]

    def describe_callee(self, expr: CallExpr, frame: Frame) -> tuple[str, str] | None:
        if expr.method_name is not None:
            return ("method", expr.method_name)
        target = expr.func
        if isinstance(target, VarExpr):
            return ("local" if frame.find(target.name) is not None else "global", target.name)
        if isinstance(target, IndexExpr) and isinstance(target.key, LiteralExpr) and isinstance(target.key.value, str):
            return ("field", target.key.value)
        return None

    def eval_expr_list(self, exprs: list[Expr], frame: Frame) -> list[Any]:
        results: list[Any] = []
        for index, expr in enumerate(exprs):
            is_last = index == len(exprs) - 1
            values = self.eval_expr(expr, frame, is_last)
            if is_last:
                results.extend(values)
            else:
                results.append(values[0] if values else None)
        return results

    def execute_block(self, block: Block, frame: Frame) -> None:
        labels = {stat.label: idx for idx, stat in enumerate(block.statements) if isinstance(stat, LabelStat)}
        index = 0
        try:
            while index < len(block.statements):
                stat = block.statements[index]
                self.set_current_line(getattr(stat, "line", block.line))
                if isinstance(stat, LabelStat):
                    index += 1
                    continue
                try:
                    self.execute_stat(stat, frame)
                except LuaGoto as jump:
                    if jump.label in labels:
                        index = labels[jump.label] + 1
                        continue
                    raise
                index += 1
        finally:
            self.close_frame(frame)

    def execute_stat(self, stat: Any, frame: Frame) -> None:
        if isinstance(stat, EmptyStat):
            return
        if isinstance(stat, BreakStat):
            raise LuaBreak()
        if isinstance(stat, GotoStat):
            raise LuaGoto(stat.label)
        if isinstance(stat, ReturnStat):
            raise LuaReturn(self.eval_expr_list(stat.values, frame))
        if isinstance(stat, DoStat):
            child = Frame(frame)
            self.execute_block(stat.block, child)
            return
        if isinstance(stat, WhileStat):
            while lua_truthy(self.eval_expr(stat.cond, frame, False)[0]):
                try:
                    self.execute_block(stat.block, Frame(frame))
                except LuaBreak:
                    break
            return
        if isinstance(stat, RepeatStat):
            while True:
                child = Frame(frame)
                try:
                    self.execute_block(stat.block, child)
                except LuaBreak:
                    break
                if lua_truthy(self.eval_expr(stat.cond, child, False)[0]):
                    break
            return
        if isinstance(stat, IfStat):
            for cond, block in stat.branches:
                if lua_truthy(self.eval_expr(cond, frame, False)[0]):
                    self.execute_block(block, Frame(frame))
                    return
            if stat.else_block is not None:
                self.execute_block(stat.else_block, Frame(frame))
            return
        if isinstance(stat, NumericForStat):
            start = self.eval_expr(stat.start, frame, False)[0]
            stop = self.eval_expr(stat.stop, frame, False)[0]
            step = self.eval_expr(stat.step, frame, False)[0] if stat.step is not None else 1
            if is_lua_int(start) and is_lua_int(stop) and is_lua_int(step):
                i = start
                if step > 0:
                    condition = lambda x: x <= stop
                else:
                    condition = lambda x: x >= stop
                while condition(i):
                    child = Frame(frame)
                    child.define(stat.name, i)
                    try:
                        self.execute_block(stat.block, child)
                    except LuaBreak:
                        break
                    i = wrap_i64(i + step)
            else:
                i = float(self.coerce_to_number(start) or 0)
                limit = float(self.coerce_to_number(stop) or 0)
                inc = float(self.coerce_to_number(step) or 0)
                if inc > 0:
                    condition = lambda x: x <= limit
                else:
                    condition = lambda x: x >= limit
                while condition(i):
                    child = Frame(frame)
                    child.define(stat.name, i)
                    try:
                        self.execute_block(stat.block, child)
                    except LuaBreak:
                        break
                    i += inc
            return
        if isinstance(stat, GenericForStat):
            values = self.eval_expr_list(stat.exps, frame)
            iterator = values[0] if len(values) >= 1 else None
            state = values[1] if len(values) >= 2 else None
            control = values[2] if len(values) >= 3 else None
            while True:
                results = self.call_value(iterator, [state, control], None)
                control = results[0] if results else None
                if control is None:
                    break
                child = Frame(frame)
                for idx, name in enumerate(stat.names):
                    child.define(name, results[idx] if idx < len(results) else None)
                try:
                    self.execute_block(stat.block, child)
                except LuaBreak:
                    break
            return
        if isinstance(stat, AssignStat):
            values = self.eval_expr_list(stat.values, frame)
            while len(values) < len(stat.targets):
                values.append(None)
            for target, value in zip(stat.targets, values):
                self.assign_target(frame, target, value)
            return
        if isinstance(stat, LocalAssignStat):
            values = self.eval_expr_list(stat.values, frame)
            while len(values) < len(stat.names):
                values.append(None)
            for name, attr, value in zip(stat.names, stat.attrs, values):
                const = attr in {"const", "close"}
                close = attr == "close"
                if close and value is not None and not self.is_closable(value):
                    self.raise_runtime(self.current_location_message(f"variable '{name}' got a non-closable value"))
                frame.define(name, value, const=const, close=close)
            return
        if isinstance(stat, LocalFunctionStat):
            cell = frame.define(stat.name, None)
            func = LuaFunction(
                stat.func.params[:],
                stat.func.vararg,
                stat.func.body,
                frame,
                self.current_location()[0],
                stat.line,
                stat.name,
            )
            cell.value = func
            return
        if isinstance(stat, CallStat):
            self.eval_call(stat.call, frame, False)
            return
        raise AssertionError(type(stat).__name__)

    def assign_target(self, frame: Frame, target: Expr, value: Any) -> None:
        if isinstance(target, VarExpr):
            self.assign_name(frame, target.name, value)
            return
        if isinstance(target, IndexExpr):
            obj = self.eval_expr(target.obj, frame, False)[0]
            key = self.eval_expr(target.key, frame, False)[0]
            self.set_index(obj, key, value)
            return
        self.raise_runtime(self.current_location_message("syntax error"))

    def call_value(
        self,
        func: Any,
        args: list[Any],
        desc: tuple[str, str] | None,
    ) -> list[Any]:
        if not isinstance(func, (LuaFunction, BuiltinFunction)):
            mm = self.get_metamethod(func, "__call")
            if mm is None:
                self.raise_runtime(self.current_location_message(f"attempt to call a {lua_type_name(func)} value"))
            return self.call_value(mm, [func, *args], desc)
        if isinstance(func, BuiltinFunction):
            kind, name = desc if desc is not None else ("global", func.name)
            self.push_frame(StackEntry("[C]", 0, kind, name=name, is_c=True))
            try:
                return func(self, args)
            finally:
                self.pop_frame()
        kind, name = desc if desc is not None else ("function", func.name_hint or "?")
        entry = StackEntry(func.source_name, func.line, kind, name=name, is_c=False)
        self.push_frame(entry)
        frame = Frame(func.closure, args[len(func.params) :] if func.vararg else [])
        for idx, param in enumerate(func.params):
            frame.define(param, args[idx] if idx < len(args) else None)
        try:
            try:
                self.execute_block(func.body, frame)
            except LuaReturn as ret:
                return ret.values
            return []
        finally:
            self.pop_frame()

    def compile_chunk(self, source: str, source_name: str) -> LuaFunction:
        lexer = Lexer(source)
        tokens = lexer.tokenize()
        parser = Parser(tokens)
        try:
            block = parser.parse()
        except LuaSyntaxError as exc:
            raise LuaSyntaxError(f"{source_name}:1: {exc.message}", incomplete=exc.incomplete)
        return LuaFunction([], True, block, self.base_frame, source_name, 1)

    def run_top_chunk(self, func: LuaFunction, args: list[Any]) -> list[Any]:
        entry = StackEntry(func.source_name, 1, "main chunk", None, is_c=False)
        self.push_frame(entry)
        frame = Frame(func.closure, args)
        try:
            try:
                self.execute_block(func.body, frame)
            except LuaReturn as ret:
                return ret.values
            return []
        finally:
            self.pop_frame()

    def format_error_message(self, err: LuaRuntimeError) -> str:
        if isinstance(err.value, str):
            header = err.value
        else:
            header = f"(error object is a {lua_type_name(err.value)} value)"
        if err.traceback:
            return f"{self.progname}: {header}\n{self.format_traceback()}"
        return f"{self.progname}: {header}"

    def package_searcher_preload(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        name = self.check_string(args, 1)
        loader = self.package_preload.rawget(name)
        if loader is None:
            return [None, f"\n\tno field package.preload['{name}']"]
        return [loader, f":preload:{name}"]

    def module_search_path(self, name: str, path_value: str, sep: str = ".", rep: str = "/") -> tuple[str | None, str | None]:
        name_path = name.replace(sep, rep)
        errors: list[str] = []
        for template in path_value.split(";"):
            candidate = template.replace("?", name_path)
            if os.path.exists(candidate):
                return candidate, None
            errors.append(f"\n\tno file '{candidate}'")
        return None, "".join(errors)

    def package_searcher_lua(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        name = self.check_string(args, 1)
        package = self.global_env.rawget("package")
        path = package.rawget("path")
        filename, errors = self.module_search_path(name, path)
        if filename is None:
            return [None, errors or ""]
        def loader(rt: Runtime, loader_args: list[Any]) -> list[Any]:
            chunk = self.load_file_chunk(filename, filename)
            return self.call_value(chunk, loader_args, ("main chunk", None))  # pragma: no cover
        chunk = self.load_file_chunk(filename, filename)
        return [chunk, filename]

    def package_searcher_c(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        name = self.check_string(args, 1)
        package = self.global_env.rawget("package")
        cpath = package.rawget("cpath")
        _, errors = self.module_search_path(name, cpath)
        return [None, errors or ""]

    def package_searcher_croot(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        package = self.global_env.rawget("package")
        cpath = package.rawget("cpath")
        root = self.check_string(args, 1).split(".", 1)[0]
        _, errors = self.module_search_path(root, cpath)
        return [None, errors or ""]

    def package_loadlib(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        path = self.check_string(args, 1)
        return [None, f"dynamic libraries not enabled; cannot load '{path}'"]

    def package_searchpath(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        name = self.check_string(args, 1)
        path = self.check_string(args, 2)
        sep = self.arg(args, 3, ".")
        rep = self.arg(args, 4, "/")
        filename, errors = self.module_search_path(name, path, sep, rep)
        if filename is None:
            return [None, errors]
        return [filename]

    def builtin_assert(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        if lua_truthy(self.arg(args, 1)):
            return args
        msg = self.arg(args, 2, "assertion failed!")
        self.raise_runtime(self.current_location_message(str(msg)) if isinstance(msg, str) else msg)

    def builtin_collectgarbage(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        option = self.arg(args, 1, "collect")
        if option == "count":
            return [0.0]
        if option == "isrunning":
            return [True]
        return [0]

    def load_file_chunk(self, filename: str, chunk_name: str | None = None) -> LuaFunction:
        try:
            with open(filename, "r", encoding="utf-8") as fh:
                source = fh.read()
        except OSError as exc:
            raise LuaRuntimeError(f"cannot open {filename}: {exc.strerror}", traceback=False)
        return self.compile_chunk(source, chunk_name or filename)

    def builtin_dofile(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        filename = self.arg(args, 1)
        if filename is None:
            source = sys.stdin.read()
            chunk = self.compile_chunk(source, "stdin")
            return self.run_top_chunk(chunk, [])
        chunk = self.load_file_chunk(self.check_string(args, 1), self.check_string(args, 1))
        return self.run_top_chunk(chunk, [])

    def builtin_error(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        message = self.arg(args, 1)
        level = self.arg(args, 2, 1)
        if isinstance(message, str) and level != 0:
            message = self.current_location_message(message)
        self.raise_runtime(message)

    def builtin_getmetatable(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        value = self.arg(args, 1)
        if isinstance(value, LuaTable):
            return [value.metatable]
        if isinstance(value, LuaFileHandle):
            return [value.metatable]
        if isinstance(value, str):
            mt = LuaTable()
            mt.rawset("__index", self.string_lib)
            return [mt]
        return [None]

    def builtin_ipairs(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        table = self.check_table(args, 1)
        def iterator(rt: Runtime, iargs: list[Any]) -> list[Any]:
            tbl = iargs[0]
            index = self.coerce_to_integer(iargs[1]) or 0
            index += 1
            value = tbl.rawget(index)
            if value is None:
                return [None]
            return [index, value]
        return [BuiltinFunction("ipairsaux", iterator), table, 0]

    def normalize_load_chunk_name(self, name: Any) -> str:
        if not isinstance(name, str) or name == "":
            return "(load)"
        if name.startswith("@"):
            return name[1:]
        if name.startswith("="):
            return name[1:]
        return f'[string "{name}"]'

    def builtin_load(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        source = self.arg(args, 1)
        name = self.normalize_load_chunk_name(self.arg(args, 2))
        env = self.arg(args, 4)
        if callable(source) or isinstance(source, (LuaFunction, BuiltinFunction)):
            self.raise_runtime(self.current_location_message("reader function loading is not supported"))
        if not isinstance(source, str):
            self.type_error(1, "string", source)
        try:
            chunk = self.compile_chunk(source, name)
        except LuaSyntaxError as exc:
            return [None, exc.message]
        if isinstance(env, LuaTable):
            chunk.closure = Frame(self.base_frame)
            chunk.closure.define("_ENV", env)
        return [chunk]

    def builtin_loadfile(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        filename = self.arg(args, 1)
        env = self.arg(args, 4)
        if filename is None:
            return [None, "loadfile from stdin is not supported"]
        filename = self.check_string(args, 1)
        try:
            chunk = self.load_file_chunk(filename, filename)
        except LuaRuntimeError as err:
            return [None, err.value]
        if isinstance(env, LuaTable):
            chunk.closure = Frame(self.base_frame)
            chunk.closure.define("_ENV", env)
        return [chunk]

    def builtin_next(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        table = self.check_table(args, 1)
        key = self.arg(args, 2)
        try:
            next_key, value = table.next_pair(key)
        except KeyError:
            self.raise_runtime(self.current_location_message("invalid key to 'next'"))
        if next_key is None:
            return [None]
        return [next_key, value]

    def builtin_pairs(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        table = self.check_table(args, 1)
        return [self.global_env.rawget("next"), table, None]

    def protected_call(self, func: Any, args: list[Any], errfunc: Any | None = None) -> list[Any]:
        try:
            return [True, *self.call_value(func, args, None)]
        except LuaRuntimeError as err:
            value = err.value
            if errfunc is not None:
                handled = self.call_value(errfunc, [value], None)
                value = handled[0] if handled else None
            return [False, value]

    def builtin_pcall(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        func = self.arg(args, 1)
        return self.protected_call(func, args[1:])

    def builtin_print(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        text = "\t".join(lua_value_to_string(arg, self) for arg in args)
        self.current_output.pyfile.write(text + "\n")
        self.current_output.pyfile.flush()
        return []

    def builtin_rawequal(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        return [self.lua_equal(self.arg(args, 1), self.arg(args, 2))]

    def builtin_rawget(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        table = self.check_table(args, 1)
        return [table.rawget(self.arg(args, 2))]

    def builtin_rawlen(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        return [self.raw_length(self.arg(args, 1))]

    def builtin_rawset(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        table = self.check_table(args, 1)
        table.rawset(self.arg(args, 2), self.arg(args, 3))
        return [table]

    def builtin_require(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        name = self.check_string(args, 1)
        loaded = self.package_loaded.rawget(name)
        if loaded is not None:
            return [loaded]
        package = self.global_env.rawget("package")
        searchers = package.rawget("searchers")
        errors = [f"module '{name}' not found:"]
        for i in range(1, searchers.rawlen() + 1):
            searcher = searchers.rawget(i)
            result = self.call_value(searcher, [name], ("global", "require"))
            loader = result[0] if result else None
            extra = result[1] if len(result) > 1 else None
            if loader is None:
                if isinstance(extra, str):
                    errors.append(extra)
                continue
            loaded_values = self.call_value(loader, [name, extra], None)
            loaded_value = loaded_values[0] if loaded_values else None
            if loaded_value is None:
                loaded_value = True
            self.package_loaded.rawset(name, loaded_value)
            return [loaded_value, extra]
        self.raise_runtime(self.current_location_message("".join(errors)))

    def builtin_select(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        index = self.arg(args, 1)
        values = args[1:]
        if index == "#":
            return [len(values)]
        ivalue = self.coerce_to_integer(index)
        if ivalue is None:
            self.type_error(1, "number", index)
        if ivalue < 0:
            ivalue = len(values) + ivalue + 1
        if ivalue < 1:
            ivalue = 1
        return values[ivalue - 1 :]

    def builtin_setmetatable(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        table = self.check_table(args, 1)
        mt = self.arg(args, 2)
        if mt is not None and not isinstance(mt, LuaTable):
            self.type_error(2, "nil or table", mt)
        table.metatable = mt
        return [table]

    def builtin_tonumber(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        value = self.arg(args, 1)
        base = self.arg(args, 2)
        if base is None:
            return [self.coerce_to_number(value)]
        ibase = self.coerce_to_integer(base)
        if ibase is None:
            self.type_error(2, "integer", base)
        if not isinstance(value, str):
            return [None]
        parsed = self.coerce_to_number(value.strip(), base=ibase)
        return [parsed]

    def builtin_tostring(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        return [lua_value_to_string(self.arg(args, 1), self)]

    def builtin_type(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        return [lua_type_name(self.arg(args, 1))]

    def builtin_warn(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        if not args:
            self.type_error(1, "string", None)
        first = self.arg(args, 1)
        if not isinstance(first, str):
            self.type_error(1, "string", first)
        if first == "@on":
            self.warning_enabled = True
            return []
        if first == "@off":
            self.warning_enabled = False
            return []
        if self.warning_enabled:
            text = "".join(lua_value_to_string(arg, None) for arg in args)
            sys.stderr.write(f"Lua warning: {text}\n")
            sys.stderr.flush()
        return []

    def builtin_xpcall(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        func = self.arg(args, 1)
        errfunc = self.arg(args, 2)
        return self.protected_call(func, args[2:], errfunc=errfunc)

    def math_atan(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        x = self.check_number(args, 1)
        y = self.arg(args, 2)
        if y is None:
            return [math.atan(x)]
        return [math.atan2(x, self.check_number(args, 2))]

    def math_ceil(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        value = self.check_number(args, 1)
        result = math.ceil(value)
        return [result if is_lua_int(value) else float(result) if not value.is_integer() else result]

    def math_floor(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        value = self.check_number(args, 1)
        result = math.floor(value)
        return [result if is_lua_int(value) else float(result) if not value.is_integer() else result]

    def math_fmod(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        return [math.fmod(float(self.check_number(args, 1)), float(self.check_number(args, 2)))]

    def math_frexp(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        m, e = math.frexp(float(self.check_number(args, 1)))
        return [m, e]

    def math_ldexp(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        return [math.ldexp(float(self.check_number(args, 1)), self.check_int(args, 2))]

    def math_log(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        x = float(self.check_number(args, 1))
        base = self.arg(args, 2)
        if base is None:
            return [math.log(x)]
        return [math.log(x, float(self.check_number(args, 2)))]

    def math_max(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        best = self.check_number(args, 1)
        for arg in args[1:]:
            if float(arg) > float(best):
                best = arg
        return [best]

    def math_min(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        best = self.check_number(args, 1)
        for arg in args[1:]:
            if float(arg) < float(best):
                best = arg
        return [best]

    def math_modf(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        value = float(self.check_number(args, 1))
        frac, integer = math.modf(value)
        if integer.is_integer() and INT_MIN <= int(integer) <= INT_MAX:
            integer_value: Any = int(integer)
        else:
            integer_value = integer
        return [integer_value, frac]

    def math_random(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        if not args:
            return [self.random.random()]
        if len(args) == 1:
            upper = self.check_int(args, 1)
            return [self.random.randint(1, upper)]
        lower = self.check_int(args, 1)
        upper = self.check_int(args, 2)
        return [self.random.randint(lower, upper)]

    def math_randomseed(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        seed1 = self.check_int(args, 1)
        seed2 = self.coerce_to_integer(self.arg(args, 2, 0)) or 0
        combined = ((seed1 & 0xFFFFFFFFFFFFFFFF) << 64) ^ (seed2 & 0xFFFFFFFFFFFFFFFF)
        self.random.seed(combined)
        return [seed1, seed2]

    def math_tointeger(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        return [self.coerce_to_integer(self.arg(args, 1))]

    def math_ult(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        a = self.check_int(args, 1) & (UINT_MOD - 1)
        b = self.check_int(args, 2) & (UINT_MOD - 1)
        return [a < b]

    def table_concat(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        table = self.check_table(args, 1)
        sep = self.arg(args, 2, "")
        i = self.coerce_to_integer(self.arg(args, 3, 1)) or 1
        j = self.coerce_to_integer(self.arg(args, 4, table.rawlen())) or table.rawlen()
        parts = [lua_value_to_string(table.rawget(index), self) for index in range(i, j + 1)]
        return [sep.join(parts)]

    def table_create(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        size = self.coerce_to_integer(self.arg(args, 1, 0)) or 0
        value = self.arg(args, 2)
        table = LuaTable()
        if value is not None:
            for index in range(1, size + 1):
                table.rawset(index, value)
        return [table]

    def table_insert(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        table = self.check_table(args, 1)
        n = table.rawlen()
        if len(args) == 2:
            pos = n + 1
            value = self.arg(args, 2)
        else:
            pos = self.check_int(args, 2)
            value = self.arg(args, 3)
        for index in range(n, pos - 1, -1):
            table.rawset(index + 1, table.rawget(index))
        table.rawset(pos, value)
        return []

    def table_move(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        src = self.check_table(args, 1)
        f = self.check_int(args, 2)
        e = self.check_int(args, 3)
        t = self.check_int(args, 4)
        dest = self.arg(args, 5, src)
        if not isinstance(dest, LuaTable):
            self.type_error(5, "table", dest)
        temp = [src.rawget(i) for i in range(f, e + 1)]
        for offset, value in enumerate(temp):
            dest.rawset(t + offset, value)
        return [dest]

    def table_pack(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        table = LuaTable()
        for index, value in enumerate(args, start=1):
            table.rawset(index, value)
        table.rawset("n", len(args))
        return [table]

    def table_remove(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        table = self.check_table(args, 1)
        pos = self.coerce_to_integer(self.arg(args, 2, table.rawlen())) or table.rawlen()
        value = table.rawget(pos)
        for index in range(pos, table.rawlen()):
            table.rawset(index, table.rawget(index + 1))
        table.rawset(table.rawlen(), None)
        return [value]

    def table_sort(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        table = self.check_table(args, 1)
        comp = self.arg(args, 2)
        values = [table.rawget(i) for i in range(1, table.rawlen() + 1)]
        def cmp(a: Any, b: Any) -> int:
            if comp is None:
                return -1 if self.compare_values("<", a, b) else (1 if self.compare_values("<", b, a) else 0)
            result = self.call_value(comp, [a, b], None)
            return -1 if lua_truthy(result[0] if result else None) else 1
        values.sort(key=functools.cmp_to_key(cmp))
        for i, value in enumerate(values, start=1):
            table.rawset(i, value)
        return [table]

    def table_unpack(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        table = self.check_table(args, 1)
        i = self.coerce_to_integer(self.arg(args, 2, 1)) or 1
        j = self.coerce_to_integer(self.arg(args, 3, table.rawlen())) or table.rawlen()
        return [table.rawget(index) for index in range(i, j + 1)]

    def string_byte(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        s = self.check_string(args, 1)
        i = self.normalize_string_index(self.coerce_to_integer(self.arg(args, 2, 1)) or 1, len(s))
        j = self.normalize_string_index(self.coerce_to_integer(self.arg(args, 3, i)) or i, len(s))
        if i > j:
            return []
        return [ord(ch) for ch in s[i - 1 : j]]

    def string_char(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        return ["".join(chr(self.check_int([value], 1)) for value in args)]

    def string_dump(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        func = self.arg(args, 1)
        if not isinstance(func, LuaFunction):
            self.type_error(1, "function", func)
        return [f"-- dumped function 0x{id(func):x}"]

    def translate_lua_pattern(self, pattern: str) -> str:
        mapping = {
            "a": "A-Za-z",
            "A": "^A-Za-z",
            "d": "0-9",
            "D": "^0-9",
            "l": "a-z",
            "L": "^a-z",
            "u": "A-Z",
            "U": "^A-Z",
            "w": "A-Za-z0-9_",
            "W": "^A-Za-z0-9_",
            "s": r"\s",
            "S": r"\S",
            "p": r"""!"#$%&'()*+,\-./:;<=>?@[\\\]^_`{|}~""",
            "x": "0-9A-Fa-f",
            "X": "^0-9A-Fa-f",
            "z": r"\x00",
        }
        out: list[str] = []
        i = 0
        while i < len(pattern):
            ch = pattern[i]
            if ch == "%":
                i += 1
                if i >= len(pattern):
                    out.append("%")
                    break
                spec = pattern[i]
                if spec in "()[]*+-?.^$":
                    out.append("\\" + spec)
                elif spec == "%":
                    out.append("%")
                elif spec in mapping:
                    mapped = mapping[spec]
                    if mapped.startswith("^") and len(mapped) > 1 and spec not in {"s", "S"}:
                        out.append(f"[{mapped}]")
                    elif mapped in {r"\s", r"\S"}:
                        out.append(mapped)
                    else:
                        out.append(f"[{mapped}]")
                else:
                    out.append(re.escape(spec))
            else:
                out.append(ch)
            i += 1
        return "".join(out)

    def string_find_impl(self, s: str, pattern: str, init: int, plain: bool) -> tuple[int, int, list[Any]] | None:
        start = max(init - 1, 0)
        if plain:
            idx = s.find(pattern, start)
            if idx < 0:
                return None
            return idx + 1, idx + len(pattern), []
        regex = re.compile(self.translate_lua_pattern(pattern))
        match = regex.search(s, start)
        if match is None:
            return None
        captures = list(match.groups())
        return match.start() + 1, match.end(), captures

    def string_find(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        s = self.check_string(args, 1)
        pattern = self.check_string(args, 2)
        init = self.coerce_to_integer(self.arg(args, 3, 1)) or 1
        plain = lua_truthy(self.arg(args, 4))
        result = self.string_find_impl(s, pattern, init, plain)
        if result is None:
            return [None]
        start, finish, captures = result
        return [start, finish, *captures]

    def string_format(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        fmt = self.check_string(args, 1)
        values: list[Any] = []
        arg_index = 2
        out = ""
        i = 0
        while i < len(fmt):
            if fmt[i] != "%":
                out += fmt[i]
                i += 1
                continue
            if i + 1 < len(fmt) and fmt[i + 1] == "%":
                out += "%"
                i += 2
                continue
            spec = fmt[i + 1]
            value = self.arg(args, arg_index)
            arg_index += 1
            if spec in "di":
                out += str(self.coerce_to_integer(value) or 0)
            elif spec in "fFeEgG":
                out += format(float(self.coerce_to_number(value) or 0.0), spec)
            elif spec == "s":
                out += lua_value_to_string(value, self)
            elif spec == "q":
                out += lua_repr_string(lua_value_to_string(value, self))
            else:
                out += "%" + spec
            i += 2
        return [out]

    def string_match(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        s = self.check_string(args, 1)
        pattern = self.check_string(args, 2)
        init = self.coerce_to_integer(self.arg(args, 3, 1)) or 1
        result = self.string_find_impl(s, pattern, init, False)
        if result is None:
            return [None]
        _, _, captures = result
        if captures:
            return captures
        regex = re.compile(self.translate_lua_pattern(pattern))
        match = regex.search(s, max(init - 1, 0))
        return [match.group(0)] if match else [None]

    def string_gmatch(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        s = self.check_string(args, 1)
        pattern = self.check_string(args, 2)
        regex = re.compile(self.translate_lua_pattern(pattern))
        iterator = iter(regex.finditer(s))
        def step(rt: Runtime, iargs: list[Any]) -> list[Any]:
            try:
                match = next(iterator)
            except StopIteration:
                return [None]
            captures = list(match.groups())
            if captures:
                return captures
            return [match.group(0)]
        return [BuiltinFunction("gmatch_aux", step)]

    def string_gsub(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        s = self.check_string(args, 1)
        pattern = self.check_string(args, 2)
        repl = self.arg(args, 3, "")
        limit = self.coerce_to_integer(self.arg(args, 4, -1)) or -1
        regex = re.compile(self.translate_lua_pattern(pattern))
        count = 0
        def replace(match: re.Match[str]) -> str:
            nonlocal count
            if limit >= 0 and count >= limit:
                return match.group(0)
            count += 1
            if isinstance(repl, str):
                text = repl.replace("%0", match.group(0))
                for idx, grp in enumerate(match.groups(), start=1):
                    text = text.replace(f"%{idx}", grp or "")
                return text
            if isinstance(repl, LuaTable):
                key = match.group(1) if match.groups() else match.group(0)
                value = repl.rawget(key)
                return match.group(0) if value is None else lua_value_to_string(value, self)
            if isinstance(repl, (LuaFunction, BuiltinFunction)):
                values = self.call_value(repl, list(match.groups()) or [match.group(0)], None)
                value = values[0] if values else None
                return match.group(0) if value is None else lua_value_to_string(value, self)
            return match.group(0)
        result = regex.sub(replace, s, 0 if limit < 0 else limit)
        return [result, count]

    def string_pack(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        fmt = self.check_string(args, 1)
        values = args[1:]
        pieces: list[bytes] = []
        index = 0
        for ch in fmt:
            if ch in "<>! =":
                continue
            value = values[index]
            index += 1
            if ch == "b":
                pieces.append(struct.pack("b", self.check_int([value], 1)))
            elif ch == "B":
                pieces.append(struct.pack("B", self.check_int([value], 1)))
            elif ch == "i":
                pieces.append(struct.pack("<q", self.check_int([value], 1)))
            elif ch == "I":
                pieces.append(struct.pack("<Q", self.check_int([value], 1) & (UINT_MOD - 1)))
            elif ch == "f":
                pieces.append(struct.pack("<f", float(self.coerce_to_number(value) or 0.0)))
            elif ch == "d":
                pieces.append(struct.pack("<d", float(self.coerce_to_number(value) or 0.0)))
            elif ch == "s":
                encoded = self.check_string([value], 1).encode()
                pieces.append(struct.pack("<I", len(encoded)) + encoded)
        return [b"".join(pieces).decode("latin1")]

    def string_packsize(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        fmt = self.check_string(args, 1)
        size = 0
        for ch in fmt:
            size += {"b": 1, "B": 1, "i": 8, "I": 8, "f": 4, "d": 8}.get(ch, 0)
        return [size]

    def string_rep(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        s = self.check_string(args, 1)
        n = self.check_int(args, 2)
        sep = self.arg(args, 3, "")
        if n <= 0:
            return [""]
        return [sep.join([s] * n)]

    def normalize_string_index(self, idx: int, length: int) -> int:
        if idx < 0:
            idx = length + idx + 1
        if idx < 1:
            idx = 1
        if idx > length:
            idx = length
        return idx

    def string_sub(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        s = self.check_string(args, 1)
        i = self.coerce_to_integer(self.arg(args, 2, 1)) or 1
        j = self.coerce_to_integer(self.arg(args, 3, -1)) or -1
        length = len(s)
        if i < 0:
            i = length + i + 1
        if j < 0:
            j = length + j + 1
        i = max(i, 1)
        j = min(j, length)
        if i > j:
            return [""]
        return [s[i - 1 : j]]

    def string_unpack(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        fmt = self.check_string(args, 1)
        data = self.check_string(args, 2).encode("latin1")
        pos = self.coerce_to_integer(self.arg(args, 3, 1)) or 1
        offset = pos - 1
        out: list[Any] = []
        for ch in fmt:
            if ch in "<>! =":
                continue
            if ch == "b":
                out.append(struct.unpack_from("b", data, offset)[0])
                offset += 1
            elif ch == "B":
                out.append(struct.unpack_from("B", data, offset)[0])
                offset += 1
            elif ch == "i":
                out.append(struct.unpack_from("<q", data, offset)[0])
                offset += 8
            elif ch == "I":
                out.append(wrap_i64(struct.unpack_from("<Q", data, offset)[0]))
                offset += 8
            elif ch == "f":
                out.append(struct.unpack_from("<f", data, offset)[0])
                offset += 4
            elif ch == "d":
                out.append(struct.unpack_from("<d", data, offset)[0])
                offset += 8
        out.append(offset + 1)
        return out

    def os_date(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        fmt = self.arg(args, 1, "%c")
        when = self.arg(args, 2)
        use_utc = False
        if isinstance(fmt, str) and fmt.startswith("!"):
            use_utc = True
            fmt = fmt[1:]
        ts = time.time() if when is None else float(self.coerce_to_number(when) or 0.0)
        dt = _datetime.datetime.utcfromtimestamp(ts) if use_utc else _datetime.datetime.fromtimestamp(ts)
        if fmt == "*t":
            table = LuaTable()
            table.rawset("year", dt.year)
            table.rawset("month", dt.month)
            table.rawset("day", dt.day)
            table.rawset("hour", dt.hour)
            table.rawset("min", dt.minute)
            table.rawset("sec", dt.second)
            table.rawset("wday", dt.isoweekday() % 7 + 1)
            table.rawset("yday", int(dt.strftime("%j")))
            table.rawset("isdst", False)
            return [table]
        return [dt.strftime(fmt)]

    def os_execute(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        command = self.arg(args, 1)
        if command is None:
            return [True]
        result = subprocess.run(command, shell=True)
        return [result.returncode == 0, "exit", result.returncode]

    def os_exit(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        code = self.arg(args, 1)
        if code is None or code is True:
            raise LuaExit(0)
        if code is False:
            raise LuaExit(1)
        raise LuaExit(self.coerce_to_integer(code) or 0)

    def os_remove(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        path = self.check_string(args, 1)
        try:
            os.remove(path)
            return [True]
        except OSError as exc:
            return [None, str(exc), exc.errno]

    def os_rename(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        old = self.check_string(args, 1)
        new = self.check_string(args, 2)
        try:
            os.rename(old, new)
            return [True]
        except OSError as exc:
            return [None, str(exc), exc.errno]

    def os_setlocale(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        loc = self.arg(args, 1)
        category_name = self.arg(args, 2, "all")
        categories = {
            "all": _locale.LC_ALL,
            "collate": _locale.LC_COLLATE,
            "ctype": _locale.LC_CTYPE,
            "monetary": _locale.LC_MONETARY,
            "numeric": _locale.LC_NUMERIC,
            "time": _locale.LC_TIME,
        }
        category = categories.get(category_name, _locale.LC_ALL)
        try:
            result = _locale.setlocale(category, loc)
            return [result]
        except Exception:
            return [None]

    def os_time(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        table = self.arg(args, 1)
        if table is None:
            return [int(time.time())]
        if not isinstance(table, LuaTable):
            self.type_error(1, "table", table)
        tm = _datetime.datetime(
            int(table.rawget("year")),
            int(table.rawget("month")),
            int(table.rawget("day")),
            int(table.rawget("hour") or 12),
            int(table.rawget("min") or 0),
            int(table.rawget("sec") or 0),
        )
        return [int(tm.timestamp())]

    def os_tmpname(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        fd, path = tempfile.mkstemp(prefix="lua_")
        os.close(fd)
        return [path]

    def io_close(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        handle = self.arg(args, 1, self.current_output)
        return self.file_close(runtime, [handle])

    def io_flush(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        self.current_output.pyfile.flush()
        return [self.current_output]

    def io_input(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        arg = self.arg(args, 1)
        if arg is None:
            return [self.current_input]
        if isinstance(arg, LuaFileHandle):
            self.current_input = arg
            return [arg]
        self.current_input = self.io_open(runtime, [arg, "r"])[0]
        return [self.current_input]

    def io_lines(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        handle = self.current_input if not args else self.io_open(runtime, [self.arg(args, 1), "r"])[0]
        return self.file_lines(runtime, [handle, *args[1:]])

    def io_open(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        filename = self.check_string(args, 1)
        mode = self.arg(args, 2, "r")
        try:
            pyfile = open(filename, mode.replace("b", ""), encoding="utf-8")
        except OSError as exc:
            return [None, str(exc), exc.errno]
        handle = LuaFileHandle(pyfile)
        handle.metatable = self.file_methods
        return [handle]

    def io_output(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        arg = self.arg(args, 1)
        if arg is None:
            return [self.current_output]
        if isinstance(arg, LuaFileHandle):
            self.current_output = arg
            return [arg]
        self.current_output = self.io_open(runtime, [arg, "w"])[0]
        return [self.current_output]

    def io_popen(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        command = self.check_string(args, 1)
        mode = self.arg(args, 2, "r")
        proc = subprocess.Popen(command, shell=True, stdout=subprocess.PIPE if "r" in mode else None, stdin=subprocess.PIPE if "w" in mode else None, text=True)
        handle = LuaFileHandle(proc.stdout if "r" in mode else proc.stdin)
        handle.metatable = self.file_methods
        return [handle]

    def read_from_handle(self, handle: LuaFileHandle, modes: list[Any]) -> list[Any]:
        if handle.closed:
            return [None]
        if not modes:
            line = handle.pyfile.readline()
            if line == "":
                return [None]
            return [line.rstrip("\n")]
        results: list[Any] = []
        for mode in modes:
            if isinstance(mode, str):
                if mode == "*a":
                    data = handle.pyfile.read()
                    results.append(data if data != "" else None)
                elif mode == "*l":
                    line = handle.pyfile.readline()
                    results.append(None if line == "" else line.rstrip("\n"))
                elif mode == "*L":
                    line = handle.pyfile.readline()
                    results.append(None if line == "" else line)
                elif mode == "*n":
                    text = ""
                    while True:
                        ch = handle.pyfile.read(1)
                        if ch == "" or ch.isspace():
                            if ch == "":
                                break
                            if text:
                                break
                            continue
                        text += ch
                    results.append(self.coerce_to_number(text) if text else None)
            else:
                count = self.coerce_to_integer(mode) or 0
                data = handle.pyfile.read(count)
                results.append(data if data != "" else None)
        return results

    def io_read(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        return self.read_from_handle(self.current_input, args)

    def io_tmpfile(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        pyfile = tempfile.TemporaryFile(mode="w+")
        handle = LuaFileHandle(pyfile)
        handle.metatable = self.file_methods
        return [handle]

    def io_type(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        handle = self.arg(args, 1)
        if not isinstance(handle, LuaFileHandle):
            return [None]
        return ["closed file" if handle.closed else "file"]

    def io_write(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        return self.file_write(runtime, [self.current_output, *args])

    def file_close(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        handle = self.arg(args, 1)
        if not isinstance(handle, LuaFileHandle):
            self.type_error(1, "FILE*", handle)
        ok, err = handle.close()
        if ok:
            return [True]
        return [None, err]

    def file_flush(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        handle = self.arg(args, 1)
        if not isinstance(handle, LuaFileHandle):
            self.type_error(1, "FILE*", handle)
        handle.pyfile.flush()
        return [handle]

    def file_lines(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        handle = self.arg(args, 1)
        modes = args[1:]
        def iterator(rt: Runtime, iargs: list[Any]) -> list[Any]:
            result = self.read_from_handle(handle, modes)
            if not result or result[0] is None:
                return [None]
            return result
        return [BuiltinFunction("lines_aux", iterator)]

    def file_read(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        handle = self.arg(args, 1)
        if not isinstance(handle, LuaFileHandle):
            self.type_error(1, "FILE*", handle)
        return self.read_from_handle(handle, args[1:])

    def file_write(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        handle = self.arg(args, 1)
        if not isinstance(handle, LuaFileHandle):
            self.type_error(1, "FILE*", handle)
        for value in args[1:]:
            handle.pyfile.write(lua_value_to_string(value, self))
        handle.pyfile.flush()
        return [handle]

    def utf8_char(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        return ["".join(chr(self.check_int([arg], 1)) for arg in args)]

    def utf8_codepoint(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        s = self.check_string(args, 1)
        i = self.coerce_to_integer(self.arg(args, 2, 1)) or 1
        j = self.coerce_to_integer(self.arg(args, 3, i)) or i
        if i < 0:
            i = len(s) + i + 1
        if j < 0:
            j = len(s) + j + 1
        return [ord(ch) for ch in s[i - 1 : j]]

    def utf8_codes(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        s = self.check_string(args, 1)
        it = iter(enumerate(s, start=1))
        def iterator(rt: Runtime, iargs: list[Any]) -> list[Any]:
            try:
                index, ch = next(it)
            except StopIteration:
                return [None]
            return [index, ord(ch)]
        return [BuiltinFunction("utf8_codes_aux", iterator)]

    def utf8_len(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        s = self.check_string(args, 1)
        i = self.coerce_to_integer(self.arg(args, 2, 1)) or 1
        j = self.coerce_to_integer(self.arg(args, 3, -1)) or -1
        if j < 0:
            j = len(s) + j + 1
        return [len(s[i - 1 : j])]

    def utf8_offset(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        s = self.check_string(args, 1)
        n = self.check_int(args, 2)
        i = self.coerce_to_integer(self.arg(args, 3, 1)) or 1
        pos = i + n
        if pos < 1 or pos > len(s) + 1:
            return [None]
        return [pos]

    def coroutine_close(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        co = self.arg(args, 1)
        if not isinstance(co, LuaCoroutine):
            self.type_error(1, "thread", co)
        co.status = "dead"
        return [True]

    def coroutine_create(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        return [LuaCoroutine(self.arg(args, 1))]

    def coroutine_isyieldable(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        return [False]

    def coroutine_resume(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        co = self.arg(args, 1)
        if not isinstance(co, LuaCoroutine):
            self.type_error(1, "thread", co)
        if co.status == "dead":
            return [False, "cannot resume dead coroutine"]
        try:
            co.status = "running"
            results = self.call_value(co.func, args[1:], None)
            co.status = "dead"
            return [True, *results]
        except LuaYield as y:
            co.status = "suspended"
            return [True, *y.values]
        except LuaRuntimeError as err:
            co.status = "dead"
            return [False, err.value]

    def coroutine_running(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        return [None, True]

    def coroutine_status(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        co = self.arg(args, 1)
        if not isinstance(co, LuaCoroutine):
            self.type_error(1, "thread", co)
        return [co.status]

    def coroutine_wrap(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        co = LuaCoroutine(self.arg(args, 1))
        def wrapper(rt: Runtime, wargs: list[Any]) -> list[Any]:
            result = self.coroutine_resume(runtime, [co, *wargs])
            if not lua_truthy(result[0]):
                self.raise_runtime(result[1])
            return result[1:]
        return [BuiltinFunction("coroutine.wrap", wrapper)]

    def coroutine_yield(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        raise LuaYield(args)

    def debug_traceback(self, runtime: Runtime, args: list[Any]) -> list[Any]:
        message = self.arg(args, 1)
        prefix = "" if message is None else lua_value_to_string(message, self) + "\n"
        return [prefix + self.format_traceback()]


def read_file(path: str) -> str:
    with open(path, "r", encoding="utf-8") as fh:
        return fh.read()


def format_usage(progname: str) -> str:
    return (
        f"usage: {progname} [options] [script [args]]\n"
        "Available options are:\n"
        "  -e stat   execute string 'stat'\n"
        "  -i        enter interactive mode after executing 'script'\n"
        "  -l mod    require library 'mod' into global 'mod'\n"
        "  -l g=mod  require library 'mod' into global 'g'\n"
        "  -v        show version information\n"
        "  -E        ignore environment variables\n"
        "  -W        turn warnings on\n"
        "  --        stop handling options\n"
        "  -         stop handling options and execute stdin"
    )


@dataclass
class ParsedCLI:
    exec_chunks: list[str] = field(default_factory=list)
    loads: list[str] = field(default_factory=list)
    interactive: bool = False
    print_version: bool = False
    ignore_env: bool = False
    warnings: bool = False
    script_name: str | None = None
    script_args: list[str] = field(default_factory=list)
    option_index: int = 0


def parse_cli(argv: list[str], progname: str) -> ParsedCLI:
    parsed = ParsedCLI()
    i = 1
    while i < len(argv):
        arg = argv[i]
        if arg == "--":
            parsed.option_index = i
            if i + 1 < len(argv):
                parsed.script_name = argv[i + 1]
                parsed.script_args = argv[i + 2 :]
            return parsed
        if arg == "-":
            parsed.option_index = i
            parsed.script_name = "-"
            parsed.script_args = argv[i + 1 :]
            return parsed
        if not arg.startswith("-") or arg == "":
            parsed.option_index = i
            parsed.script_name = arg
            parsed.script_args = argv[i + 1 :]
            return parsed
        if arg == "-i":
            parsed.interactive = True
            i += 1
            continue
        if arg == "-v":
            parsed.print_version = True
            i += 1
            continue
        if arg == "-E":
            parsed.ignore_env = True
            i += 1
            continue
        if arg == "-W":
            parsed.warnings = True
            i += 1
            continue
        if arg.startswith("-e"):
            value = arg[2:] if len(arg) > 2 else None
            if value is None or value == "":
                if i + 1 >= len(argv):
                    raise LuaRuntimeError(f"'-e' needs argument", traceback=False)
                value = argv[i + 1]
                i += 1
            parsed.exec_chunks.append(value)
            i += 1
            continue
        if arg.startswith("-l"):
            value = arg[2:] if len(arg) > 2 else None
            if value is None or value == "":
                if i + 1 >= len(argv):
                    raise LuaRuntimeError(f"'-l' needs argument", traceback=False)
                value = argv[i + 1]
                i += 1
            parsed.loads.append(value)
            i += 1
            continue
        raise LuaRuntimeError(f"unrecognized option '{arg}'", traceback=False)
    parsed.option_index = 0
    return parsed


def build_arg_table(argv: list[str], script_pos: int) -> LuaTable:
    table = LuaTable()
    if script_pos == 0:
        for idx, value in enumerate(argv):
            table.rawset(idx, value)
        return table
    for pos, value in enumerate(argv):
        table.rawset(pos - script_pos, value)
    return table


def execute_chunk(runtime: Runtime, source: str, chunk_name: str, args: list[Any], top_level: bool) -> int:
    try:
        chunk = runtime.compile_chunk(source, chunk_name)
    except LuaSyntaxError as exc:
        sys.stderr.write(f"{runtime.progname}: {exc.message}\n")
        return 1
    try:
        if top_level:
            runtime.run_top_chunk(chunk, args)
        else:
            runtime.call_value(chunk, args, None)
        return 0
    except LuaExit as exc:
        raise exc
    except LuaRuntimeError as err:
        sys.stderr.write(runtime.format_error_message(err) + "\n")
        return 1


def load_init_chunk(runtime: Runtime, value: str) -> int:
    if value.startswith("@"):
        filename = value[1:]
        try:
            chunk = runtime.load_file_chunk(filename, filename)
            runtime.run_top_chunk(chunk, [])
            return 0
        except LuaRuntimeError as err:
            sys.stderr.write(f"{runtime.progname}: {err.value}\n")
            return 1
        except LuaExit as exc:
            raise exc
    status = execute_chunk(runtime, value, "LUA_INIT", [], True)
    return status


def do_require_binding(runtime: Runtime, spec: str) -> int:
    target = spec
    module = spec
    if "=" in spec:
        target, module = spec.split("=", 1)
    try:
        results = runtime.builtin_require(runtime, [module])
    except LuaRuntimeError as err:
        sys.stderr.write(runtime.format_error_message(err) + "\n")
        return 1
    runtime.global_env.rawset(target, results[0] if results else None)
    return 0


def repl(runtime: Runtime) -> int:
    banner_printed = False
    if runtime.stdin_is_tty or runtime.stdout_is_tty:
        sys.stdout.write(VERSION_LINE + "\n")
        sys.stdout.flush()
        banner_printed = True
    buffer = ""
    prompt = "> "
    prompt2 = ">> "
    while True:
        env_prompt = runtime.global_env.rawget("_PROMPT")
        env_prompt2 = runtime.global_env.rawget("_PROMPT2")
        current_prompt = env_prompt if isinstance(env_prompt, str) else prompt
        current_prompt2 = env_prompt2 if isinstance(env_prompt2, str) else prompt2
        sys.stdout.write(current_prompt if not buffer else current_prompt2)
        sys.stdout.flush()
        line = sys.stdin.readline()
        if line == "":
            if not buffer:
                if banner_printed:
                    sys.stdout.write("\n")
                break
            sys.stderr.write(f"stdin:1: unexpected symbol near <eof>\n")
            break
        buffer += line
        if buffer.strip() == "":
            buffer = ""
            continue
        is_expr = False
        try:
            chunk = runtime.compile_chunk(buffer, "stdin")
        except LuaSyntaxError as exc:
            try:
                expr_chunk = runtime.compile_chunk("return " + buffer, "stdin")
                chunk = expr_chunk
                is_expr = True
            except LuaSyntaxError as expr_exc:
                if exc.incomplete or expr_exc.incomplete:
                    continue
                sys.stderr.write(f"stdin:1: {exc.message.split(': ', 1)[-1]}\n")
                buffer = ""
                continue
        try:
            values = runtime.run_top_chunk(chunk, [])
            if is_expr and values:
                sys.stdout.write("\t".join(lua_value_to_string(v, runtime) for v in values) + "\n")
                sys.stdout.flush()
        except LuaRuntimeError as err:
            header = err.value if isinstance(err.value, str) else f"(error object is a {lua_type_name(err.value)} value)"
            if isinstance(header, str) and header.startswith("stdin:"):
                sys.stderr.write(header + "\n" + runtime.format_traceback() + "\n")
            else:
                sys.stderr.write(f"{header}\n{runtime.format_traceback()}\n")
        except LuaExit as exc:
            raise exc
        buffer = ""
    return 0


def main(argv: list[str] | None = None) -> int:
    argv = argv or sys.argv
    progname = argv[0]
    stdin_is_tty = sys.stdin.isatty()
    stdout_is_tty = sys.stdout.isatty()
    runtime = Runtime(progname, stdin_is_tty, stdout_is_tty)
    try:
        parsed = parse_cli(argv, progname)
    except LuaRuntimeError as err:
        sys.stderr.write(f"{progname}: {err.value}\n{format_usage(progname)}\n")
        return 1

    script_pos = parsed.option_index if parsed.script_name is not None else 0
    runtime.global_env.rawset("arg", build_arg_table(argv, script_pos))

    if parsed.warnings:
        runtime.warning_enabled = True

    if not parsed.ignore_env:
        init_value = os.getenv("LUA_INIT_5_5")
        if init_value is None:
            init_value = os.getenv("LUA_INIT")
        if init_value is not None:
            try:
                status = load_init_chunk(runtime, init_value)
            except LuaExit as exc:
                return exc.code
            if status != 0:
                return status

    if parsed.print_version:
        print(VERSION_LINE)

    for spec in parsed.loads:
        status = do_require_binding(runtime, spec)
        if status != 0:
            return status

    for chunk in parsed.exec_chunks:
        try:
            status = execute_chunk(runtime, chunk, "(command line)", [], True)
        except LuaExit as exc:
            return exc.code
        if status != 0:
            return status

    if parsed.script_name is not None:
        if parsed.script_name == "-":
            source = sys.stdin.read()
            try:
                status = execute_chunk(runtime, source, "stdin", parsed.script_args, True)
            except LuaExit as exc:
                return exc.code
            if status != 0:
                return status
            if parsed.interactive:
                try:
                    return repl(runtime)
                except LuaExit as exc:
                    return exc.code
            return 0
        try:
            source = read_file(parsed.script_name)
        except OSError as exc:
            sys.stderr.write(f"{progname}: cannot open {parsed.script_name}: {exc.strerror}\n")
            return 1
        try:
            status = execute_chunk(runtime, source, parsed.script_name, parsed.script_args, True)
        except LuaExit as exc:
            return exc.code
        if status != 0:
            return status
        if parsed.interactive:
            try:
                return repl(runtime)
            except LuaExit as exc:
                return exc.code
        return 0

    if parsed.print_version and not parsed.interactive and not stdin_is_tty:
        return 0

    if parsed.interactive:
        try:
            return repl(runtime)
        except LuaExit as exc:
            return exc.code

    if stdin_is_tty:
        try:
            return repl(runtime)
        except LuaExit as exc:
            return exc.code

    source = sys.stdin.read()
    try:
        status = execute_chunk(runtime, source, "stdin", [], True)
    except LuaExit as exc:
        return exc.code
    return 0 if status != 0 else 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except LuaExit as exc:
        raise SystemExit(exc.code)

